import json, collections, itertools
p='runs/mw_protocol_v3_3r3_batch8_fresh_20260911/final_all8_assembled.json'
d=json.load(open(p))
ch={c['contract']['chapter_contract_id']:c for c in d['chapters']}
by_fact=collections.defaultdict(set)
trigger=collections.defaultdict(set)
when_active=collections.defaultdict(set)
for cid,c in ch.items():
    sc=c['contract']['substantive_content']
    for fr in sc['fact_requirements']: by_fact[fr['fact_path']].add(cid)
    for r in c['contract'].get('conditional_applicability_rules',[]):
        for fp in r['triggering_fact_paths']: trigger[fp].add(cid)
        for fp in r['required_when_active_fact_paths']: when_active[fp].add(cid)
print('facts in fact_requirements:',len(by_fact),'trigger paths:',len(trigger),'when_active paths:',len(when_active))
print('conditional-only paths (not in requirements):', len(set(when_active)-set(by_fact)))
print('sample trigger paths:', list(sorted(trigger))[:5])
# scheduling
sched=collections.defaultdict(set); deps_of=collections.defaultdict(set)
for cid,c in ch.items():
    for dep in c['contract'].get('dependency_ids',[]):
        sched[dep].add(cid); deps_of[cid].add(dep)
print('total scheduling edges:', sum(len(v) for v in sched.values()))
# topo check
indeg={cid:0 for cid in ch}
for dep,ds in sched.items():
    for t in ds: indeg[t]+=1
q=[c for c in ch if indeg[c]==0]; seen=0
while q:
    n=q.pop(); seen+=1
    for t in sched.get(n,()):
        indeg[t]-=1
        if indeg[t]==0: q.append(t)
print('topo visited', seen, 'of', len(ch), '=> acyclic' if seen==len(ch) else '=> CYCLE')
# consistency pairs
pairs=collections.defaultdict(set)
allfacts=set(by_fact)|set(trigger)|set(when_active)
for fp in allfacts:
    members=by_fact[fp]|trigger[fp]|when_active[fp]
    for a,b in itertools.combinations(sorted(members),2): pairs[(a,b)].add(fp)
print('consistency edges:', len(pairs), 'chapters with >=1 partner:', len({x for p in pairs for x in p}), 'of', len(ch))
# closure function
def closure(facts):
    direct={cid for fp in facts for cid in (by_fact[fp]|trigger[fp]|when_active[fp])}
    affected=set(direct); nxt=set(direct)
    while nxt:
        n2=set()
        for cid in sorted(nxt):
            for (a,b),shared in pairs.items():
                if a==cid and b not in affected: n2.add(b)
                elif b==cid and a not in affected: n2.add(a)
            for t in sched.get(cid,()):
                if t not in affected: n2.add(t)
        affected|=n2; nxt=n2
    return direct,affected
for f in ['picos.primary_endpoint','picos.population_summary','diagram.phase_arm_structure']:
    dir_,aff=closure([f]); print(f, 'direct',len(dir_),'affected',len(aff))
# find dose facts
voc=[v for v in d['fact_vocabulary'] if 'dose' in v or 'endpoint' in v or 'estimand' in v]
print('dose/endpoint/estimand vocab size:', len(voc))
fan={f:len(by_fact[f]|trigger[f]|when_active[f]) for f in voc}
print('top dose/endpoint fan-out:', sorted(fan.items(), key=lambda kv:-kv[1])[:12])
